import {exams,selectableExams,verifiedAt,scheduleUrl} from './exams.js';
import {product,tracks,parts,officialSources} from './product.js';
import {KEY,REVIEW_SUCCESSES_REQUIRED,dateKey,addDays,daysUntil,initial,validate,playable,firstAttempts,percent,submitAnswer,randomSample} from './core.js';

const main=document.querySelector('main');
const dialog=document.querySelector('dialog');
const notice=document.querySelector('#notice');
const esc=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const letter=index=>String.fromCharCode(65+index);
const number=value=>new Intl.NumberFormat('zh-HK').format(value);
const fmtDate=day=>new Intl.DateTimeFormat('zh-HK',{year:'numeric',month:'long',day:'numeric'}).format(new Date(day+'T00:00:00+08:00'));
const partMeta=id=>parts.find(part=>part.id===id)||{id,title:'綜合課題',short:'綜合'};
const displayPart=id=>track().id==='sqe'&&id===7?6:id;

let state=initial();
let questions=[];
let storageProblem='';
let noticeTimeout;
let lastAction=Date.now();
let lastTick=Date.now();
let busy=false;

// 清除舊私人原型及測試版本的本機資料；公開版本只使用新版的獨立儲存空間。
try{localStorage.removeItem('eaqe-prototype-v1');localStorage.removeItem('propexam-hk-v2')}catch{}

function read(){try{const raw=localStorage.getItem(KEY);return raw?validate(JSON.parse(raw)):initial()}catch{storageProblem='學習紀錄未能讀取。';return initial()}}
state=read();
function toast(message,persistent=false){clearTimeout(noticeTimeout);notice.textContent=message;if(!persistent)noticeTimeout=setTimeout(()=>notice.textContent='',4000)}
async function mutate(fn,redraw=true){const operation=()=>{if(storageProblem){toast(storageProblem,true);return false}const next=structuredClone(read());try{fn(next);localStorage.setItem(KEY,JSON.stringify(next));state=next;if(redraw)render();return true}catch(error){toast(error.name==='QuotaExceededError'?'儲存空間不足，請先匯出紀錄。':error.message,true);return false}};return navigator.locks?navigator.locks.request(KEY,operation):operation()}
const route=()=>location.hash.slice(1)||'home';
function go(hash){if(route()===hash){render();main.focus()}else location.hash=hash}
const track=()=>tracks[state.settings.track]||tracks.eaqe;
const trackQuestions=()=>questions.filter(question=>(question.examTracks||['eaqe']).includes(track().id));
const paidActive=()=>state.entitlement?.plan==='full'&&(!state.entitlement.expiresAt||state.entitlement.expiresAt>=dateKey());
const unlocked=question=>paidActive()||question.free===true;
const attempts=()=>{const ids=new Set(questions.map(question=>question.id));return state.attempts.filter(attempt=>ids.has(attempt.questionId))};
const reviews=()=>{const ids=new Set(questions.map(question=>question.id));return Object.entries(state.reviews).filter(([id])=>ids.has(id))};
const trackAttempts=()=>{const ids=new Set(trackQuestions().map(question=>question.id));return attempts().filter(attempt=>ids.has(attempt.questionId))};
const due=()=>{const ids=new Set(trackQuestions().map(question=>question.id));return reviews().filter(([id,review])=>ids.has(id)&&review.due<=dateKey())};
const answeredIds=()=>new Set(attempts().map(attempt=>attempt.questionId));
const attemptsFor=id=>attempts().filter(attempt=>attempt.questionId===id).sort((a,b)=>a.at-b.at);
const current=()=>questions.find(question=>question.id===state.session?.ids[state.session.index]);
function statsHTML(items){return `<div class="stats">${items.map(([value,label])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div>`}
function trackSwitch(){return `<div class="track-switch" role="group" aria-label="選擇考試"><button data-action="set-track" data-track="eaqe" class="${track().id==='eaqe'?'active':''}"><strong>大牌</strong><span>EAQE</span></button><button data-action="set-track" data-track="sqe" class="${track().id==='sqe'?'active':''}"><strong>細牌</strong><span>SQE</span></button></div>`}
function examSelect(trackId=track().id,selectedDate=state.settings.examDate){const available=selectableExams(dateKey(),selectedDate,trackId);return `<label class="field">目標場次<select name="examDate"><option value="">稍後決定</option>${available.map(exam=>`<option value="${exam.date}" ${exam.date===selectedDate?'selected':''}>${fmtDate(exam.date)} · ${exam.time}</option>`).join('')}</select></label>`}
function nextPool(){const pool=trackQuestions().filter(unlocked);const answered=answeredIds();const pending=pool.filter(question=>!answered.has(question.id));if(pending.length)return pending.slice(0,10);const dueIds=new Set(due().map(([id])=>id));const duePool=pool.filter(question=>dueIds.has(question.id));return duePool.length?duePool.slice(0,10):pool.slice(0,10)}

function home(){const pool=trackQuestions();const free=pool.filter(question=>question.free);const session=state.session&&current()?state.session:null;const exam=exams.find(item=>item.date===state.settings.examDate&&item.track===track().id);const day=exam?daysUntil(exam.date):null;const today=attempts().filter(attempt=>attempt.day===dateKey());
 return `<section class="public-hero"><div><p class="eyebrow">${product.tagline}</p><h1>先做題，<br>再真正理解答案。</h1><p class="hero-copy">原創題目、逐題解說、錯題重溫及進度分析，集中處理香港地產牌照考試的取分重點。</p>${trackSwitch()}<div class="hero-actions"><button class="primary" data-action="home-start">${session?'繼續練習':'免費開始'} <span>→</span></button><a class="secondary" href="#pricing">查看 60 日方案</a></div><p class="microcopy">第一部分免費體驗 · 無需付款資料</p></div><aside class="exam-panel public"><span class="eyebrow">${track().short} · ${track().code}</span><h2>${track().name}</h2><div class="countdown public-count">${day===null?'—':Math.max(0,day)}<span>日</span></div><p>${exam?fmtDate(exam.date):'尚未選擇考試場次'}</p><form id="onboarding" class="exam-choice">${examSelect()}<button class="secondary" type="submit">儲存</button></form></aside></section>
 <section class="product-proof">${statsHTML([[number(pool.length),'原創練習題'],[free.length,'免費題目'],[track().duration,'考試時間']])}</section>
 <section class="how-it-works"><div class="section-heading"><p class="eyebrow">使用方式</p><h2>每次練習都完成一個學習循環</h2></div><ol><li><span>01</span><div><h3>選擇考試</h3><p>切換大牌或細牌，只顯示相關範圍。</p></div></li><li><span>02</span><div><h3>按綱要練習</h3><p>完成題目後立即查看答案及概念。</p></div></li><li><span>03</span><div><h3>集中處理錯題</h3><p>答錯或不確定的題目自動加入重溫。</p></div></li><li><span>04</span><div><h3>查看進步</h3><p>按綱要分析正確率、覆蓋及使用時間。</p></div></li></ol></section>
 <section class="exam-comparison"><div class="section-heading"><p class="eyebrow">大牌與細牌</p><h2>重疊範圍共用，專屬內容清楚分開</h2></div><div class="comparison-grid"><div><h3>共同範圍</h3><p>六個核心知識範圍</p><p class="muted">行業、條例、相關法例、查冊、樓宇知識及租務。</p></div><div><h3>大牌專屬</h3><p>估價及業務管理</p><p class="muted">EAQE 第 6 及第 8 部分。</p></div><div><h3>考試形式</h3><p>${track().format}</p><p class="muted">${track().pass}</p></div></div><p class="source-note">資料依據地產代理監管局考試資料，核實日期：${officialSources.verifiedAt}。<a class="text-link" href="${officialSources.exam}" target="_blank" rel="noopener noreferrer">查看官方資料 ↗</a></p></section>
 ${today.length?`<section class="return-strip"><div><strong>今日已完成 ${today.length} 題</strong><span>所有紀錄只屬於此瀏覽器的目前使用者。</span></div><a class="secondary" href="#analysis">查看進度</a></section>`:''}`}

function learning(){const pool=trackQuestions();return `<div class="page-heading"><div><p class="eyebrow">${track().short} · ${track().code}</p><h1>學習範圍</h1><p class="muted">由概念重點直接進入相關練習</p></div>${trackSwitch()}</div><div class="syllabus-list">${parts.filter(part=>track().parts.includes(part.id)).map(part=>{const list=pool.filter(question=>question.part===part.id);const locked=!paidActive()&&!list.some(question=>question.free);const concepts=new Set(list.map(question=>question.concept)).size;return `<div class="chapter-row"><span class="chapter-number">${String(displayPart(part.id)).padStart(2,'0')}</span><div><div class="chapter-title">${esc(part.title)}</div><div class="chapter-meta">${list.length} 題 · ${concepts} 個概念${part.eaqeOnly?' · 大牌專屬':''}</div></div><a class="${locked?'locked-link':'quiet'}" href="${locked?'#pricing':`#part/${part.id}`}">${locked?'解鎖':'學習'} <span aria-hidden="true">${locked?'◇':'→'}</span></a></div>`}).join('')}</div>`}

function partPage(){const id=Number(route().split('/')[1]);const part=partMeta(id);const list=trackQuestions().filter(question=>question.part===id);if(!track().parts.includes(id))return '<div class="empty"><h1>此範圍不屬於目前考試</h1><a class="secondary" href="#learning">返回學習</a></div>';if(!paidActive()&&!list.some(question=>question.free))return paywall(part.title);const visible=list.filter(unlocked);const unique=[];const seen=new Set();for(const question of visible){if(seen.has(question.concept))continue;seen.add(question.concept);unique.push(question)}return `<article class="concept-review"><a class="quiet back-link" href="#learning">← 返回學習範圍</a><p class="eyebrow">第 ${displayPart(id)} 部分</p><h1>${esc(part.title)}</h1><p class="muted">${unique.length} 個概念重點 · 每項均可直接練習</p>${unique.map(question=>`<section class="concept-note"><h2>${esc(question.concept)}</h2><p>${esc(question.explanation)}</p><button class="quiet" data-action="review-one" data-id="${esc(question.id)}">練習這個概念 →</button></section>`).join('')}</article>`}

function practice(){const pool=trackQuestions();const unlockedPool=pool.filter(unlocked);const first=firstAttempts({attempts:attempts()});return `<div class="page-heading"><div><p class="eyebrow">${track().short} · ${track().code}</p><h1>練習題庫</h1><p class="muted">按官方綱要分類的原創題目</p></div><div class="page-actions"><a class="secondary" href="#history">錯題與紀錄</a><a class="secondary" href="#concepts">弱項概念</a>${state.session&&current()&&unlocked(current())?'<a class="primary" href="#quiz">繼續練習</a>':''}</div></div><section class="practice-overview"><div><span class="eyebrow">目前題庫</span><p class="library-total">${number(pool.length)}<small> 題</small></p><p class="muted">免費可做 ${unlockedPool.length} 題 · ${paidActive()?'60 日通行證已啟用':'完整題庫需使用通行證'}</p></div><button class="primary" data-action="start-next">開始 10 題 <span>→</span></button></section>${due().length?`<section class="due-strip"><div><strong>${due().length} 題已到重溫日期</strong><span>來自你在本瀏覽器的作答紀錄</span></div><button class="secondary" data-action="review-due">立即重溫</button></section>`:''}<div class="set-list">${parts.filter(part=>track().parts.includes(part.id)).map(part=>{const list=pool.filter(question=>question.part===part.id);const accessible=list.filter(unlocked);const completed=new Set(first.filter(attempt=>list.some(question=>question.id===attempt.questionId)).map(attempt=>attempt.questionId)).size;return `<div class="chapter-row"><span class="chapter-number">${String(displayPart(part.id)).padStart(2,'0')}</span><div><div class="chapter-title">${esc(part.title)}</div><div class="chapter-meta">${list.length} 題 · 已完成 ${completed} 題${part.eaqeOnly?' · 大牌專屬':''}</div><div class="bar compact"><span style="width:${list.length?completed/list.length*100:0}%"></span></div></div>${accessible.length?`<button class="quiet" data-action="start-part" data-part="${part.id}">開始 →</button>`:'<a class="locked-link" href="#pricing">解鎖 ◇</a>'}</div>`}).join('')}</div>`}

function paywall(title='完整內容'){return `<section class="paywall"><span class="lock-shape">◇</span><p class="eyebrow">60 日完整通行證</p><h1>解鎖${esc(title)}</h1><p>一次付款 HK$${product.price}，在 ${product.accessDays} 日內使用全部題目、逐題解說、錯題重溫及進度分析。</p><a class="primary" href="#pricing">查看方案 →</a></section>`}
function pricing(){return `<section class="pricing-hero"><p class="eyebrow">簡單、一次性收費</p><h1>用 60 日完成一輪有系統的備試</h1><p>固定使用期，不會自動續費。先免費完成第一部分，再決定是否開通。</p></section><div class="pricing-grid"><section class="plan free"><p class="eyebrow">免費體驗</p><h2>HK$0</h2><ul><li>第一部分練習題</li><li>逐題答案及解說</li><li>個人錯題紀錄</li><li>手機及電腦瀏覽</li></ul><button class="secondary" data-action="home-start">立即試做</button></section><section class="plan paid"><span class="plan-badge">建議方案</span><p class="eyebrow">完整通行證</p><h2>HK$${product.price}<small> / ${product.accessDays} 日</small></h2><ul><li>大牌及細牌完整原創題庫</li><li>全部概念解說及弱項重溫</li><li>跨章練習及進度分析</li><li>官方考試資料入口</li></ul><button class="primary" data-action="buy">購買 60 日通行證 →</button><p class="microcopy">付款功能正在接入；目前不會收取款項。</p></section></div><section class="pricing-note"><h2>為何採用 60 日通行證？</h2><p>牌照考試的學習期有明確終點。固定使用期比自動續費更容易預算，也避免考試後忘記取消訂閱。</p></section>`}

function history(){const completed=trackQuestions().filter(unlocked).filter(question=>attemptsFor(question.id).length);const pendingIds=new Set(reviews().map(([id])=>id));const pending=completed.filter(question=>pendingIds.has(question.id));const reviewed=completed.filter(question=>attemptsFor(question.id).length>1);const rows=list=>list.length?list.map(question=>{const records=attemptsFor(question.id);const last=records.at(-1);const review=state.reviews[question.id];const reviewState=review?review.status==='consolidate'?` · 鞏固進度 ${Math.min(review.successes||0,REVIEW_SUCCESSES_REQUIRED)} / ${REVIEW_SUCCESSES_REQUIRED}`:review.status==='uncertain'?' · 不確定，待重溫':' · 答錯，待重溫':'';return `<div class="record-row"><div><div class="record-title">${esc(question.concept)}</div><div class="chapter-meta">第 ${displayPart(question.part)} 部分 · 作答 ${records.length} 次 · 最近：${last.correct?'正確':'錯誤'}${last.uncertain?'／不確定':''}${reviewState}</div></div><button class="quiet" data-action="review-one" data-id="${esc(question.id)}">再做一次 →</button></div>`}).join(''):'<p class="muted">暫無紀錄。</p>';return `<div class="page-heading"><div><a class="quiet back-link" href="#practice">← 返回題庫</a><h1>錯題與練習紀錄</h1><p class="muted">只顯示你在此瀏覽器建立的紀錄</p></div></div><div class="analysis-stats">${statsHTML([[completed.length,'已完成'],[pending.length,'待重溫'],[reviewed.length,'已再次練習']])}</div><section class="record-section"><h2>待重溫</h2><p class="muted">在兩個不同日期答對後，題目會自動移出此清單。</p>${rows(pending)}</section><section class="record-section"><h2>已再次練習</h2>${rows(reviewed)}</section><section class="record-section"><h2>全部已完成</h2>${rows(completed)}</section>`}
function concepts(){const weakIds=new Set(reviews().map(([id])=>id));const pool=trackQuestions().filter(unlocked).filter(question=>weakIds.has(question.id));if(!pool.length)return `<div class="empty"><span class="empty-symbol">○</span><h1>尚未建立弱項</h1><p>答錯或標記不確定的題目，會在此整理成概念清單。</p><a class="primary" href="#practice">開始練習</a></div>`;const unique=[];const seen=new Set();for(const question of pool){const key=`${question.part}:${question.concept}`;if(!seen.has(key)){seen.add(key);unique.push(question)}}return `<div class="page-heading"><div><a class="quiet back-link" href="#practice">← 返回題庫</a><h1>弱項概念</h1><p class="muted">根據目前尚待鞏固的題目整理</p></div><span class="chip">${unique.length} 個概念</span></div><article class="concept-review">${parts.filter(part=>track().parts.includes(part.id)&&unique.some(question=>question.part===part.id)).map(part=>`<details class="concept-group" open><summary class="concept-part"><span>${String(displayPart(part.id)).padStart(2,'0')}</span><h2>${esc(part.title)}</h2></summary>${unique.filter(question=>question.part===part.id).map(question=>`<div class="concept-note"><h3>${esc(question.concept)}</h3><p>${esc(question.explanation)}</p><button class="quiet" data-action="review-one" data-id="${esc(question.id)}">再做一次 →</button></div>`).join('')}</details>`).join('')}</article>`}

function explanation(question,attempt){return `<section class="feedback ${attempt.correct?'':'error'}" aria-labelledby="feedback-title"><h2 id="feedback-title" tabindex="-1">${attempt.correct?'✓ 答案正確':'✕ 答案錯誤'} <span class="chip">正確答案 ${letter(question.answer)}</span></h2><p class="eyebrow">核心概念</p><h3>${esc(question.concept)}</h3><p>${esc(question.explanation)}</p>${question.optionNotes?.length?`<details><summary>逐項查看選項</summary>${question.optionNotes.map((note,index)=>`<p><strong>${letter(index)}</strong> · ${esc(note)}</p>`).join('')}</details>`:''}</section>`}
function quiz(){const session=state.session;const question=current();if(!session||!question)return '<div class="empty"><h1>尚未開始練習</h1><a class="primary" href="#practice">前往題庫</a></div>';if(!unlocked(question))return paywall('這道題目');const attempt=session.result;return `<section class="quiz"><div class="quiz-top"><a class="quiet" href="#practice">← 返回題庫</a><span>${session.index+1} / ${session.ids.length} 題</span></div><div class="quiz-progress"><span style="width:${(session.index+1)/session.ids.length*100}%"></span></div><div class="inline-group"><span class="eyebrow">第 ${displayPart(question.part)} 部分 · ${esc(partMeta(question.part).short)}</span><span class="chip">${esc(question.type||'獨立題')}</span></div><h1 class="question" id="question-title" tabindex="-1">${esc(question.stem)}</h1><form id="answer-form"><fieldset class="options" aria-labelledby="question-title">${question.options.map((option,index)=>{const correct=attempt&&index===question.answer;const wrong=attempt&&!attempt.correct&&index===attempt.selected;return `<label class="option ${correct?'correct':wrong?'wrong':''}"><input type="radio" name="answer" value="${index}" ${attempt?'disabled':''} ${(attempt?attempt.selected:session.draft?.selected)===index?'checked':''}><span class="letter">${letter(index)}</span><span>${esc(option)}</span></label>`}).join('')}</fieldset><div class="question-actions"><label class="check-label"><input type="checkbox" name="uncertain" ${(attempt?attempt.uncertain:session.draft?.uncertain)?'checked':''} ${attempt?'disabled':''}>仍然不確定</label>${attempt?`<button type="button" class="primary" data-action="next">${session.index===session.ids.length-1?'查看結果':'下一題'} →</button>`:'<button class="primary" type="submit">提交答案</button>'}</div><p id="answer-error" class="error-text" role="alert"></p></form>${attempt?explanation(question,attempt):''}${attempt?`<div class="question-actions post-answer-actions"><button class="secondary" data-action="mark-uncertain" ${attempt.uncertain?'disabled':''}>${attempt.uncertain?'已加入重溫':'仍然不確定，加入重溫'}</button><span class="saved-label">✓ 已儲存${attempt.correct&&!attempt.uncertain?'':' · 已加入重溫'}</span></div>`:''}</section>`}
function summary(){const finished=state.lastSession;if(!finished)return practice();const sessionAttempts=attempts().filter(attempt=>attempt.id.startsWith(finished.id+':'));return `<section class="quiz"><span class="eyebrow">本輪練習完成</span><h1>${esc(finished.title)}</h1><div class="summary-number">${sessionAttempts.filter(attempt=>attempt.correct).length}<small> / ${sessionAttempts.length} 題正確</small></div><p class="muted">${sessionAttempts.filter(attempt=>!attempt.correct||attempt.uncertain).length} 題已加入重溫</p><div class="summary-results">${sessionAttempts.map(attempt=>{const question=questions.find(item=>item.id===attempt.questionId);return `<details class="review-row"><summary>${attempt.correct?'✓':'✕'} ${esc(question?.concept)}</summary>${question?explanation(question,attempt):''}</details>`}).join('')}</div><a class="primary" href="#practice">返回題庫</a></section>`}
function analysis(){const all=trackAttempts();const first=firstAttempts({attempts:all});const accuracy=percent(first);const covered=new Set(all.map(attempt=>attempt.questionId)).size;const days=Array.from({length:7},(_,index)=>addDays(dateKey(),index-6));const times=days.map(day=>(state.usage[day]||0)/60);const max=Math.max(25,...times);return `<div class="page-heading"><div><p class="eyebrow">${track().short} · ${track().code}</p><h1>學習進度</h1><p class="muted">只計算你在此瀏覽器的作答</p></div></div><div class="analysis-stats">${statsHTML([[all.length,'累計作答'],[accuracy===null?'—':accuracy+'%','首次正確率'],[covered+' / '+trackQuestions().length,'題庫覆蓋']])}</div><div class="analysis-layout"><section><h2>各部分表現</h2>${parts.filter(part=>track().parts.includes(part.id)).map(part=>{const list=first.filter(attempt=>attempt.part===part.id);const value=percent(list);return `<div class="performance-row"><div class="performance-label"><span>${String(displayPart(part.id)).padStart(2,'0')} ${esc(part.short)}</span><span>${value===null?'未評估':`${value}% · ${list.length} 題`}</span></div><div class="bar"><span style="width:${value||0}%"></span></div></div>`}).join('')}</section><section><h2>最近七日 · 全站使用時間</h2><p><strong style="font-size:36px">${Math.floor((state.usage[dateKey()]||0)/60)}</strong> <span class="muted">分鐘 · 今日</span></p><div class="week-chart">${days.map((day,index)=>`<div class="day-column"><span>${Math.floor(times[index])}</span><div class="day-bar" style="height:${times[index]/max*110}px"></div><span>${day.slice(8)}</span></div>`).join('')}</div><div class="weak-link"><h3>集中處理個人錯題</h3><a class="secondary" href="#history">查看待重溫題目 →</a></div></section></div>`}

function render(){const currentRoute=route();const selected=['practice','quiz','summary','history','concepts'].includes(currentRoute)?'practice':currentRoute.startsWith('part/')?'learning':currentRoute;document.querySelectorAll('header nav a').forEach(link=>link.hash==='#'+selected?link.setAttribute('aria-current','page'):link.removeAttribute('aria-current'));main.innerHTML=currentRoute==='learning'?learning():currentRoute.startsWith('part/')?partPage():currentRoute==='practice'?practice():currentRoute==='history'?history():currentRoute==='concepts'?concepts():currentRoute==='quiz'?quiz():currentRoute==='summary'?summary():currentRoute==='analysis'?analysis():currentRoute==='pricing'?pricing():home();document.title=`${selected==='home'?'主頁':selected==='practice'?'練習題庫':selected==='analysis'?'學習進度':selected==='learning'?'學習範圍':selected==='pricing'?'方案':product.name}｜${product.name}`}
async function start(pool,title,mode='practice'){const accessible=pool.filter(unlocked);if(!accessible.length){go('pricing');return}if(state.session&&current()){dialog.innerHTML='<div class="dialog-head"><h2>開始另一輪練習？</h2></div><p>已提交的答案會保留，目前未完成的練習將會結束。</p><div class="inline-group"><button class="primary" id="confirm-start">開始</button><button class="secondary" data-action="close-dialog">取消</button></div>';dialog.showModal();const confirmed=await new Promise(resolve=>{dialog.querySelector('#confirm-start').onclick=()=>{resolve(true);dialog.close()};dialog.addEventListener('close',()=>resolve(false),{once:true})});if(!confirmed)return}const selected=accessible.length>10&&mode!=='part-all'?randomSample(accessible,10):accessible;const ok=await mutate(next=>{next.session={id:crypto.randomUUID(),title,mode,ids:selected.map(question=>question.id),index:0,result:null,draft:{},activeMs:0}});if(ok)go('quiz')}
function settings(selectedTrack=track().id){const selectedDate=exams.find(exam=>exam.date===state.settings.examDate)?.track===selectedTrack?state.settings.examDate:'';dialog.innerHTML=`<div class="dialog-head"><h2 id="settings-title">設定</h2><button class="quiet" data-action="close-dialog">✕</button></div><form id="settings-form"><label class="field">考試類別<select name="track"><option value="eaqe" ${selectedTrack==='eaqe'?'selected':''}>大牌 · 地產代理資格考試</option><option value="sqe" ${selectedTrack==='sqe'?'selected':''}>細牌 · 營業員資格考試</option></select></label>${examSelect(selectedTrack,selectedDate)}<button class="primary" type="submit">儲存設定</button></form><hr><h3>學習紀錄</h3><p class="muted">作答、錯題及進度目前只儲存在這個瀏覽器。共用電腦使用後可在此清除。</p><div class="inline-group"><button class="secondary" data-action="export">匯出我的紀錄</button><button class="quiet" data-action="clear-records">清除本機紀錄</button></div><p class="source-note"><a class="text-link" href="${scheduleUrl}" target="_blank" rel="noopener noreferrer">官方考試時間表 ↗</a> · 核實 ${verifiedAt}</p>`;if(!dialog.open)dialog.showModal()}

document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
 if(action==='settings')settings();
 if(action==='close-dialog')dialog.close();
 if(action==='set-track'){await mutate(next=>{next.settings.track=button.dataset.track;const selected=exams.find(exam=>exam.date===next.settings.examDate);if(selected?.track!==next.settings.track)next.settings.examDate='';next.session=null});toast(`已切換至${track().name}。`)}
 if(action==='home-start'){if(state.session&&current())go('quiz');else await start(nextPool(),'快速練習')}
 if(action==='start-next')await start(nextPool(),'快速練習');
 if(action==='start-part'){const id=Number(button.dataset.part);await start(trackQuestions().filter(question=>question.part===id),`第 ${displayPart(id)} 部分練習`)}
 if(action==='review-due'){const ids=new Set(due().map(([id])=>id));await start(trackQuestions().filter(question=>ids.has(question.id)),'到期錯題重溫','review')}
 if(action==='review-one'){const question=questions.find(item=>item.id===button.dataset.id);if(question)await start([question],`重溫：${question.concept}`,'review')}
 if(action==='next'){const completed=state.session?.index===state.session?.ids.length-1;const ok=await mutate(next=>{if(!next.session?.result)return;if(completed){next.lastSession={id:next.session.id,title:next.session.title};next.session=null}else{next.session.index+=1;next.session.result=null;next.session.draft={};next.session.activeMs=0}});if(ok){if(completed)go('summary');else{render();window.scrollTo({top:0});document.querySelector('#question-title')?.focus()}}}
 if(action==='mark-uncertain'){const question=current();const result=state.session?.result;if(question&&result){await mutate(next=>{const saved=next.attempts.find(attempt=>attempt.id===result.id);if(saved)saved.uncertain=true;if(next.session?.result)next.session.result.uncertain=true;next.reviews[question.id]={status:'uncertain',due:addDays(dateKey(),1),lastAt:Date.now(),successes:0}});toast('已加入翌日重溫。')}}
 if(action==='buy'){dialog.innerHTML=`<div class="dialog-head"><h2>60 日通行證</h2><button class="quiet" data-action="close-dialog">✕</button></div><p>方案已設定為 HK$${product.price}／${product.accessDays} 日。安全付款及帳戶系統仍在接入，現時不會收取款項。</p><a class="secondary" href="#practice" data-action="close-dialog">先使用免費題目</a>`;dialog.showModal()}
 if(action==='export'){const raw=localStorage.getItem(KEY)||JSON.stringify(state);const url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`propexam-records-${dateKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 if(action==='clear-records'){dialog.innerHTML='<div class="dialog-head"><h2>清除本機紀錄？</h2><button class="quiet" data-action="close-dialog">✕</button></div><p>此操作會刪除這個瀏覽器內的作答、錯題及進度紀錄。</p><div class="inline-group"><button class="primary" data-action="confirm-clear">確認清除</button><button class="secondary" data-action="close-dialog">取消</button></div>';dialog.showModal()}
 if(action==='confirm-clear'){localStorage.removeItem(KEY);storageProblem='';state=initial();dialog.close();render();toast('本機學習紀錄已清除。')}
});
document.addEventListener('submit',async event=>{const form=event.target;if(!['onboarding','settings-form','answer-form'].includes(form.id))return;event.preventDefault();const data=new FormData(form);
 if(form.id==='onboarding'||form.id==='settings-form'){const selectedTrack=String(data.get('track')||track().id);let examDate=String(data.get('examDate')||'');if(exams.find(exam=>exam.date===examDate)?.track!==selectedTrack)examDate='';if(examDate&&!selectableExams(dateKey(),state.settings.examDate,selectedTrack).some(exam=>exam.date===examDate)){toast('請選擇已公布的考試場次。');return}await mutate(next=>{if(next.settings.track!==selectedTrack)next.session=null;next.settings.track=selectedTrack;next.settings.examDate=examDate});if(dialog.open)dialog.close();toast('設定已儲存。')}
 if(form.id==='answer-form'){if(busy)return;const choice=data.get('answer');if(choice===null){document.querySelector('#answer-error').textContent='請先選擇答案。';return}busy=true;try{const question=current();const ok=await mutate(next=>submitAnswer(next,question,Number(choice),data.get('uncertain')==='on'));if(ok)document.querySelector('#feedback-title')?.focus({preventScroll:true})}finally{busy=false}}
});
document.addEventListener('change',event=>{if(event.target.matches('#settings-form [name="track"]')){settings(event.target.value);return}if(event.target.closest('#answer-form')&&state.session&&!state.session.result){const data=new FormData(document.querySelector('#answer-form'));mutate(next=>{if(next.session&&!next.session.result)next.session.draft={selected:data.get('answer')===null?null:Number(data.get('answer')),uncertain:data.get('uncertain')==='on'}},false)}});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();main.focus()});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});main.focus({preventScroll:true})});
window.addEventListener('storage',event=>{if(event.key===KEY){state=read();render()}});
['pointerdown','keydown','scroll'].forEach(name=>document.addEventListener(name,()=>lastAction=Date.now(),{passive:true}));
setInterval(()=>{const now=Date.now();const delta=Math.min(5000,now-lastTick);lastTick=now;if(document.hidden||now-lastAction>120000)return;mutate(next=>{next.usage[dateKey(now)]=(next.usage[dateKey(now)]||0)+delta/1000;if(route()==='quiz'&&next.session&&!next.session.result)next.session.activeMs+=delta},false)},5000);

try{const response=await fetch('./questions.json');if(!response.ok)throw Error('題庫載入失敗。');const raw=await response.json();if(!Array.isArray(raw)||raw.some(question=>!playable(question)||!Array.isArray(question.examTracks)||typeof question.free!=='boolean'||question.optionNotes?.length!==5))throw Error('題庫資料不完整。');questions=raw;if(!questions.length)throw Error('題庫尚未準備完成。');await mutate(next=>{const ids=new Set(questions.filter(question=>paidActive()||question.free).map(question=>question.id));if(next.session&&!next.session.ids.every(id=>ids.has(id)))next.session=null},false);render()}catch(error){main.innerHTML=`<div class="empty"><h1>未能載入題庫</h1><p>${esc(error.message)}</p><a class="secondary" href="./">重新載入</a></div>`}
